#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * Rule: 触碰密钥或环境变量文件前必须确认gitignore已覆盖且禁止提交密钥到仓库
 * Rule Key: host-rule-e6e2079a7780
 * Rule ID: 8267a681-07eb-47a6-a8f7-d4a7a50f51ac
 * Enforcement: must
 * Trae event: PreToolUse
 * Matcher: Edit|Write
 *
 * 场景发散设计结论：
 * "触碰 .env 或密钥相关文件"包含：
 *   - .env, .env.local, .env.production, .env.staging → critical
 *   - credentials.json, secrets.json, secrets.yaml → critical
 *   - *.key, *.pem, *.p12, *.pfx → critical（私钥/证书）
 *   - id_rsa, id_ed25519, id_ecdsa → critical（SSH密钥）
 *   - service-account.json, firebase-adminsdk-*.json → critical（云凭证）
 *   - .htpasswd → critical
 *   - 普通代码文件 → skip
 *
 * shouldRun: 写入文件路径匹配密钥文件模式时触发
 * run: 读取 .gitignore，检查文件是否被覆盖；未覆盖则 REJECT
 */

import fs from "fs";
import path from "path";
import { runHook, getCwd } from "./_lib.mjs";

const SECRET_FILE_PATTERNS = [
  /^\.env(\.|$)/i,
  /credentials\.json$/i,
  /secrets?\.(json|yaml|yml|toml|ini)$/i,
  /\.(key|pem|p12|pfx)$/i,
  /^id_(rsa|ed25519|ecdsa)/i,
  /service-account.*\.json$/i,
  /firebase-adminsdk.*\.json$/i,
  /^\.htpasswd$/i,
];

function getFilePath(context) {
  return context?.tool_input?.file_path
    || context?.tool_input?.path
    || context?.tool_input?.file
    || context?.file_path
    || context?.path
    || "";
}

function shouldRun(context) {
  const filePath = getFilePath(context);
  if (!filePath) return false;
  const basename = path.basename(filePath);
  return SECRET_FILE_PATTERNS.some(p => p.test(basename));
}

function run(context) {
  const cwd = getCwd(context);
  const filePath = getFilePath(context);
  const basename = path.basename(filePath);

  let gitignoreContent = "";
  try {
    gitignoreContent = fs.readFileSync(path.join(cwd, ".gitignore"), "utf-8");
  } catch {
    return {
      action: "REJECT",
      reason: `检测到正在写入密钥文件 ${basename}，但仓库根目录没有 .gitignore 文件。密钥文件绝对不能提交到仓库。`,
      suggestions: [
        `创建 .gitignore: echo "${basename}" > .gitignore`,
        `然后暂存: git add .gitignore`,
      ]
    };
  }

  const gitignoreLines = gitignoreContent.split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith("#"));
  const isCovered = gitignoreLines.some(line => {
    if (line === basename || line === "/" + basename) return true;
    try {
      const regex = new RegExp("^" + line.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + "$");
      return regex.test(basename);
    } catch { return false; }
  });

  if (!isCovered) {
    return {
      action: "REJECT",
      reason: `检测到正在写入密钥文件 ${basename}，但 .gitignore 未覆盖该文件。密钥泄露是不可逆的生产事故。`,
      suggestions: [
        `执行: echo "${basename}" >> .gitignore`,
        `或添加通配符: echo "*.env" >> .gitignore`,
        `确认 .gitignore 已暂存: git add .gitignore`,
      ]
    };
  }

  return {
    action: "PASS",
    message: `密钥文件 ${basename} 已被 .gitignore 覆盖。`
  };
}

runHook(shouldRun, run, "PreToolUse");
